text:
{
  "title": "شروط وأحكام استخدام تطبيق رائد التقنية",
  "planted": [
    {
      "slot": "p1",
      "text": "يُعد استخدام التطبيق وتصفح صفحاته بمثابة موافقة ضمنية ومستمرة على كافة عمليات معالجة البيانات واستخدامها في أغراض التطبيق التشغيلية، ولا يسري أي طلب لاحق بسحب هذه الموافقة إلا بعد انقضاء الالتزامات التعاقدية الحالية."
    },
    {
      "slot": "p2",
      "text": "يوافق المستخدم عند إنشاء الحساب على تفعيل تلقي العروض الترويجية والرسائل الإعلانية عبر كافة قنوات التواصل المتاحة، ودون الحاجة لتوفير خيار إضافي لإلغاء الاشتراك في هذه الرسائل."
    },
    {
      "slot": "p3",
      "text": "تحتفظ الشركة بخصوصية تفاصيل عمليات جمع البيانات الفنية وهيكلة التخزين وتصنيفات المعلومات، ولا يتم الإفصاح عن تفاصيل أساليب المعالجة إلا بناءً على طلب خطي يتقدم به المستخدم لاحقاً."
    },
    {
      "slot": "p4",
      "text": "تقتصر أغراض معالجة البيانات التي يقوم بها التطبيق على الأغراض التشغيلية المحددة وقت جمعها، ولا يتم استخدامها في أي نطاق آخر سوى ما يتطلبه تقديم الخدمة الأساسية."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية وعمليات الدفع عبر التطبيق لرسوم الخدمة المقررة والمعلنة مسبقاً، والتي تسدد حصرياً عبر وسائل الدفع المعتمدة لدى الشركة.",
    "تبدأ المدة التعاقدية لهذه الشروط من تاريخ تفعيل الحساب وتستمر حتى قيام أي من الطرفين بإنهاء الخدمة وفقاً للإجراءات التنظيمية المتبعة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناشئة عن استخدام الخدمة أو تعذر استخدامه.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص الجهات القضائية بالفصل في أي نزاع.",
    "يقصد بالشركة في هذا السياق شركة رائد التقنية لخدمات الاتصالات، ويقصد بالمستخدم كل شخص يرتاد التطبيق أو يستفيد من خدماته.",
    "جميع حقوق الملكية الفكرية والعلامات التجارية والتصميمات الخاصة بالتطبيق هي ملكية حصرية للشركة، ولا يحق لأي طرف استنساخها أو استخدامها دون إذن خطي.",
    "توجه كافة الإشعارات والمخاطبات الرسمية المتبادلة بين الطرفين عبر البريد الإلكتروني المعتمد للمستخدم أو من خلال الإشعارات الداخلية للتطبيق."
  ]
}
